    std::cout << "Markdown: " << input_markdown << "\n";
    std::cout << "HTML:     " << output_html << "\n";

    return 0;
}

std::string convert_markdown_to_html(const std::string& input_str)
{
    std::string output_str;

    // Substitutions de caractères simples
    output_str.replace(std::regex::all_begin(input_str, std::regex(R"(^|\s)\*\*(.+?)\*\*(\s|$)"), std::regex::match_format),
                        std::regex::all_end(input_str, std::regex(R"(^|\s)\*\*(.+?)\*\*(\s|$)")),
                        "<strong>$1</strong>");

    output_str.replace(std::regex::all_begin(input_str, std::regex(R"(^|\s)\*\*(.+?)\*\*(\s|$)"), std::regex::match_format),
                        std::regex::all_end(input_str, std::regex(R"(^|\s)\*\*(.+?)\*\*(\s|$)")),
                        "</strong>");

    output_str.replace(std::regex::all_begin(input_str, std::regex(R"(^|\s)\*\*(.+?)\*\*(\s|$)"), std::regex::match_format),
                        std::regex::all_end(input_str, std::regex(R"(^|\s)\*\*(.+?)\*\*(\s|$)")),
                        "</strong>");

    output_str.replace(std::regex::all_begin(input_str, std::regex(R"(^|\s)\*(.+?)\*(\s|$)"), std::regex::match_format),
                        std::regex::all_end(input_str, std::regex(R"(^|\s)\*(.+?)\*(\s|$)")),
                        "<em>$1</em>");

    output_str.replace(std::regex::all_begin(input_str, std::regex(R"(^|\s)\*(.+?)\*(\s|$)"), std::regex::match_format),
                        std::regex::all_end(input_str, std::regex(R"(^|\s)\*(.+?)\*(\s|$)")),
                        "</em>");

    return output_str;
}
```

Cette implémentation utilise la fonction `std::regex` de la bibliothèque `<regex>` pour effectuer des substitutions de caractères simples de la forme `**texte**` et `*texte*`. Les expressions régulières utilisées sont les suivantes:

- `R"(^|\s)\*\*(.+?)\*\*(\s|$)` : Matches des mots entiers encadrés par deux caractères de guillemets (`**`) qui peuvent apparaître au début (`^`) ou après un espace (`\s`), et qui peuvent être suivi d'un espace (`\s`) ou se terminer (`$`).
- `R"(^|\s)\*(.+?)\*(\s|$)` : Similaire à l'expression régulière précédente, mais pour les mots entiers encadrés par un seul caractère d'astérisque (`*`).

Notez que cette implémentation est très simple et ne traite que les cas les plus basiques de Markdown. Il existe de nombreux autres cas à considérer, comme les listes, les titres, les blocs de code, les liens, etc., pour un traitement exhaustif de la conversion de Markdown en HTML. De plus, cette implémentation ne tient pas compte des options de style ou des extensions de Markdown.

