#include <SDL2_image/SDL_image.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

enum {
    SNAKE_HEAD,
    SNAKE_BODY,
    FOOD,
    WALL
};

typedef struct {
    int x;
    int y;
} Point;

int main(int argc, char* argv[]) {
    // Initialiser les variables
    int gridWidth = WINDOW_WIDTH / 20;
    int gridHeight = WINDOW_HEIGHT / 20;
    int score = 0;
    int level = 1;
    int framesPerSecond = 10;
    SDL_Window* window;
    SDL_Renderer* renderer;
    SDL_Event event;

    // Charger les images
    SDL_Surface* headSurface = IMG_Load("head.png");
    SDL_Surface* bodySurface = IMG_Load("body.png");
    SDL_Surface* foodSurface = IMG_Load("food.png");
    SDL_Surface* wallSurface = IMG_Load("wall.png");

    if(headSurface == NULL || bodySurface == NULL || foodSurface == NULL || wallSurface == NULL) {
        printf("Impossible de charger les images!\n");
        return 1;
    }

    SDL_Texture* headTexture = SDL_CreateTextureFromSurface(renderer, headSurface);
    SDL_Texture* bodyTexture = SDL_CreateTextureFromSurface(renderer, bodySurface);
    SDL_Texture* foodTexture = SDL_CreateTextureFromSurface(renderer, foodSurface);
    SDL_Texture* wallTexture = SDL_CreateTextureFromSurface(renderer, wallSurface);

    // Initialiser la fenêtre de la console
    if(SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("Erreur d'initialisation de SDL!\n");
        return 1;
    }

    window = SDL_CreateWindow(
        "Jeu du serpent",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN | SDL_WINDOW_RESIZABLE);

    if(window == NULL) {
        printf("Impossible de créer la fenêtre de la console!\n");
        return 1;
    }

    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if(renderer == NULL) {
        printf("Impossible de créer le renderer!\n");
        return 1;
    }

    // Définir la logique de jeu
    Point snakeHead = {gridWidth/2, gridHeight/2};
    Point snakeBody[100]; // Initialiser à un grand nombre pour éviter les problèmes de mémoire
    int snakeBodySize = 1; // Compteur pour suivre la taille du serpent
    bool gamePaused = false;

    srand(time(NULL));

    while(true) {
        while(SDL_PollEvent(&event)) {
            switch(event.type) {
                case SDL_QUIT:
                    quit = true;
                    break;
                case SDL_KEYDOWN:
                    switch(event.key.keysym.sym) {
                        case SDLK_ESCAPE:
                            quit = true;
                            break;
                        case SDLK_p:
                            gamePaused = !gamePaused;
                            break;
                    }
                    break;
            }
        }

        if(!gamePaused) {
            // Gérer les mouvements du serpent
            int moveX = 0, moveY = 0;
            if(SDL_GetKeyboardState(NULL)[SDL_SCANCODE_LEFT]) moveX -= 1;
            if(SDL_GetKeyboardState(NULL)[SDL_SCANCODE_RIGHT]) moveX += 1;
            if(SDL_GetKeyboardState(NULL)[SDL_SCANCODE_UP]) moveY -= 1;
            if(SDL_GetKeyboardState(NULL)[SDL_SCANCODE_DOWN]) moveY += 1;

            if(moveX != 0 || moveY != 0) {
                snakeHead.x += moveX;
                snakeHead.y += moveY;

                if(snakeHead.x < 0 || snakeHead.x >= gridWidth || snakeHead.y < 0 || snakeHead.y >= gridHeight) {
                    // Mort par collision avec les murs
                    quit = true;
                } else if(snakeBodyContainsPoint(snakeHead)) {
                    // Mort par collision avec le serpent
                    quit = true;
                } else {
                    // Ajouter une nouvelle case au serpent
                    Point newBodyPoint = {snakeHead.x - moveX, snakeHead.y - moveY};
                    snakeBody[snakeBodySize++] = newBodyPoint;
                }
            }

            // Gérer les collisions avec les objets de nourriture et les murs
            bool foodEaten = false;
            for(int I=0; I<gridWidth*gridHeight; i++) {
                int row = I/gridWidth;
                int col = I%gridWidth;

                if(grid[row][col] == FOOD) {
                    grid[row][col] = WALL;
                    score += 10*level;
                    level++;

                    // Générer un nouveau point de nourriture
                    Point foodPoint = generateRandomFoodPoint();
                    while(snakeBodyContainsPoint(foodPoint)) {
                        foodPoint = generateRandomFoodPoint();
                    }
                    grid[foodPoint.y][foodPoint.x] = FOOD;
                } else if(grid[row][col] == WALL) {
                    quit = true;
                }
            }

            // Rafraichir l'écran
            SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
            SDL_RenderClear(renderer);

            // Dessiner les murs
            for(int I=0; I<gridWidth; i++) {
                for(int j=0; j<gridHeight; j++) {
                    if(grid[j][i] == WALL) {
                        SDL_Rect wallRect = {(i+1)*20, j*20, 18, 18};
                        SDL_RenderCopy(renderer, wallTexture, NULL, &wallRect);
                    }
                }
            }

            // Dessiner le serpent
            for(int I=0; I<snakeBodySize; i++) {
                SDL_Rect snakeRect = {(snakeBody[i].x+1)*20, (snakeBody[i].y)*20, 18, 18};
                if(i == 0) { // Dessiner la tête du serpent
                    SDL_RenderCopy(renderer, headTexture, NULL, &snakeRect);
                } else { // Dessiner les segments du serpent
                    SDL_RenderCopy(renderer, bodyTexture, NULL, &snakeRect);
                }
            }

            // Dessiner l'objet de nourriture
            if(grid[foodPoint.y][foodPoint.x] == FOOD) {
                SDL_Rect foodRect = {(foodPoint.x+1)*20, (foodPoint.y)*20, 18, 18};
                SDL_RenderCopy(renderer, foodTexture, NULL, &foodRect);
            }

            // Afficher le score et le niveau
            char scoreText[32];
            sprintf(scoreText, "Score: %d", score);
            SDL_Surface* scoreSurface = TTF_RenderText_Solid(font, scoreText, textColor);
            SDL_Rect scoreRect = {(WINDOW_WIDTH - 120), 10, scoreSurface->w, scoreSurface->h};
            SDL_BlitSurface(scoreSurface, NULL, screenSurface, &scoreRect);
            SDL_FreeSurface(scoreSurface);

            char levelText[32];
            sprintf(levelText, "Niveau %d", level);
            SDL_Surface* levelSurface = TTF_RenderText_Solid(font, levelText, textColor);
            SDL_Rect levelRect = {(WINDOW_WIDTH - 80), 30, levelSurface->w, levelSurface->h};
            SDL_BlitSurface(levelSurface, NULL, screenSurface, &levelRect);
            SDL_FreeSurface(levelSurface);

            SDL_UpdateWindowSurface(window);

            SDL_Delay(1000/framesPerSecond);
        }
    }

    // Nettoyer les ressources
    SDL_DestroyTexture(headTexture);
    SDL_DestroyTexture(bodyTexture);
    SDL_DestroyTexture(foodTexture);
    SDL_DestroyTexture(wallTexture);
    SDL_FreeSurface(headSurface);
    SDL_FreeSurface(bodySurface);
    SDL_FreeSurface(foodSurface);
    SDL_FreeSurface(wallSurface);
    TTF_CloseFont(font);
    SDL_DestroyRenderer(renderer);
