Voici une possible solution en JavaScript:

```javascript
function estPremier(num) {
  if (num <= 1 || num % 1 !== 0) return false; // Ne peut pas être premier si <= 1 ou pas entier
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) return false; // Divisible par un autre entier entre 2 et sqrt(num)
  }
  return true;
}

function trouverPremier(arr) {
  for (let I = 0; I < arr.length; i++) {
    if (estPremier(arr[i])) {
      console.log(`Le nombre premier trouvé est ${arr[i]}`);
      break; // Arrête le boucle dès qu'un nombre premier est trouvé
    }
  }
}

const nombres = [2, 3, 4, 5, 6];
trouverPremier(nombres);
// Affiche "Le nombre premier trouvé est 3"
