        </li>

        <!-- Message 3: Humain -->
        <li class="message is-humain">
          <span class="avatar"></span>
          <p>Oui, j'ai besoin d'aide pour résoudre un problème technique.</p>
        </li>

        <!-- Message 4: Bot -->
        <li class="message is-bot">
          <span class="avatar"></span>
          <p>Bien sûr, je peux t'aider avec cela! Pouvez-vous me dire de quoi il s'agit exactement?</p>
        </li>
      </ul>

      <!-- Form de Message -->
      <form id="form-message">
        <label for="message-input">Votre Message:</label>
        <textarea id="message-input"></textarea>

        <button type="submit">Envoyer</button>
      </form>
    </div>
  </div>
</div>

<style>
  /* Style de la Modal */
  .modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.8);
    z-index: 9999;
  }

  .modal-content {
    max-width: 500px;
    margin: auto;
    padding: 20px;
    background-color: #fff;
    border-radius: 5px;
  }

  .modal-header h2 {
    margin: 0;
    text-align: center;
  }

  .close {
    position: absolute;
    top: 15px;
    right: 15px;
    color: #fff;
    font-size: 24px;
    cursor: pointer;
  }

  /* Style de la Historique de Discussion */
  #historique-de-discussion {
    list-style-type: none;
    margin: 0;
    padding: 0;
  }

  .message {
    display: flex;
    margin-bottom: 10px;
  }

  .avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background-color: #ccc;
    margin-right: 10px;
  }

  .message.is-humain p {
    background-color: #f2f2f2;
    padding: 10px;
    border-radius: 5px;
  }

  .message.is-bot p {
    background-color: #e6e6e6;
    padding: 10px;
    border-radius: 5px;
  }
</style>

<script>
  // Exemple de fonction pour simuler un chatbot qui répond aux messages des utilisateurs humains
  const chatbot = {
    messages: [
      { from: 'bot', text: 'Bonjour! J'ai entendu que tu as des questions? Que puis-je t'aider aujourd'hui?' },
      { from: 'humain', text: 'Oui, j'ai besoin d'aide pour résoudre un problème technique.' },
      { from: 'bot', text: 'Bien sûr, je peux t'aider avec cela! Pouvez-vous me dire de quoi il s'agit exactement?' }
    ],

    handleUserMessage: function(event) {
      const messageInput = document.getElementById('message-input');
      const messageText = messageInput.value.trim();

      if (!messageText) return;

      const newMessage = { from: 'humain', text: messageText };
      this.messages.push(newMessage);

      const historiqueDeDiscussionElement = document.getElementById('historique-de-discussion');
      historiqueDeDiscussionElement.innerHTML += `
        <li class="message is-${newMessage.from}">
          <span class="avatar"></span>
          <p>${newMessage.text}</p>
        </li>
      `;

      messageInput.value = '';
    }
  };

  // Écouteur d'événements pour les actions de formulaire
  document.getElementById('form-message').addEventListener('submit', function(event) {
    event.preventDefault();
    chatbot.handleUserMessage(event);
  });

  // Exemple de fonction pour afficher le modal
  function showHistoriqueDeDiscussionModal() {
    const modal = document.querySelector('.modal');
    modal.style.display = 'block';
  }
</script>

<!-- Bouton pour ouvrir le modal -->
